#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "blosclz.h"
int main() {
  int length = 100000;
  int maxout = length;
  unsigned char *input = malloc(length);
  unsigned char *output = malloc(maxout + 1);
  srand(1);
  for (int i = 0; i < length; i++) input[i] = rand() & 0xff;
  // make last 1/4 compressible (zeros)
  memset(input + length - length/4, 0, length/4);
  int r = blosclz_compress(9, input, length, output, maxout, 1);
  printf("result=%d\n", r);
  return 0;
}
EOF
